        static_cast<double>(exponent) / 128.0;
    const double hundredths_db =
        -std::trunc(
            std::abs(normalized) * std::abs(normalized) *
            std::abs(normalized) * 10000.0);
    const double attenuation = std::pow(
        10.0, hundredths_db / 2000.0);
